import { RootState } from "./root-reducer";

export const initialState = (props?: TreeProps<any>): RootState => ({
  nodes: {
    // Changes together
    open: { filtered: {}, unfiltered: props?.initialOpenState ?? {} },
    focus: { id: null, treeFocused: false },
    edit: { id: null },
    drag: {
      id: null,
      selectedIds: [],
      destinationParentId: null,
      destinationIndex: null,
    },
    selection: { ids: new Set(), anchor: null, mostRecent: null },
  },
  dnd: {
    cursor: { type: "none" },
    dragId: null,
    dragIds: [],
    parentId: null,
    index: -1,
  },
});

    return this.state.nodes.edit.id !== null;
  }

  get isFiltered() {
    return !!this.props.searchTerm?.trim();
  }

  get hasFocus() {
    return this.state.nodes.focus.treeFocused;
  }

  get hasNoSelection() {
    return this.state.nodes.selection.ids.size === 0;
  }

  get hasOneSelection() {
    return this.state.nodes.selection.ids.size === 1;
  }

  get hasMultipleSelections() {
    return this.state.nodes.selection.ids.size > 1;
  }

  isSelected(id?: string) {
    if (!id) return false;
    return this.state.nodes.selection.ids.has(id);
  }

  isOpen(id?: string) {
    if (!id) return false;
    if (id === ROOT_ID) return true;
    const def = this.props.openByDefault ?? true;
    if (this.isFiltered) {
      return this.state.nodes.open.filtered[id] ?? true; // Filtered folders are always opened by default
    } else {
      return this.state.nodes.open.unfiltered[id] ?? def;
    }
  }

  isEditable(data: T) {
    return this.isActionPossible(data, this.props.disableEdit);
  }

  isDraggable(data: T) {
    return this.isActionPossible(data, this.props.disableDrag);
  }

  isSelectable(data: T) {
    return this.isActionPossible(data, this.props.disableSelect);
  }

  private isActionPossible(data: T, disabler: string | boolean | BoolFunc<T> = () => false) {
    return !utils.access(data, disabler);
  }

import { ActionTypes } from "../types/utils";

/* Types */
export type OpenMap = { [id: string]: boolean };
export type OpenSlice = { unfiltered: OpenMap; filtered: OpenMap };

/* Actions */
export const actions = {
  open(id: string, filtered: boolean) {
    return { type: "VISIBILITY_OPEN" as const, id, filtered };
  },
  close(id: string, filtered: boolean) {
    return { type: "VISIBILITY_CLOSE" as const, id, filtered };
  },
  toggle(id: string, filtered: boolean) {
    return { type: "VISIBILITY_TOGGLE" as const, id, filtered };
  },
  clear(filtered: boolean) {
    return { type: "VISIBILITY_CLEAR" as const, filtered };
  },
};

/* Reducer */

function openMapReducer(state: OpenMap = {}, action: ActionTypes<typeof actions>) {
  if (action.type === "VISIBILITY_OPEN") {
    return { ...state, [action.id]: true };
  } else if (action.type === "VISIBILITY_CLOSE") {
    return { ...state, [action.id]: false };
  } else if (action.type === "VISIBILITY_TOGGLE") {
    const prev = state[action.id];
    return { ...state, [action.id]: !prev };
  } else if (action.type === "VISIBILITY_CLEAR") {
    return {};
  } else {
    return state;
  }
}

export function reducer(
  state: OpenSlice = { filtered: {}, unfiltered: {} },
  action: ActionTypes<typeof actions>,
): OpenSlice {
  if (!action.type.startsWith("VISIBILITY")) return state;
  if (action.filtered) {
    return { ...state, filtered: openMapReducer(state.filtered, action) };
  } else {
    return { ...state, unfiltered: openMapReducer(state.unfiltered, action) };
  }
}

import { useSyncExternalStore } from 'react'
import { dataService, type DataService, type DataServiceState } from '../../services/data/data_service'

const snapshots = new WeakMap<DataService, DataServiceState>()

function isSameDataServiceState(first: DataServiceState, second: DataServiceState) {
    return first.project === second.project
        && first.runningAgents === second.runningAgents
        && first.snapshot === second.snapshot
}

function getProjectStateSnapshot(service: DataService): DataServiceState {
    const nextSnapshot = service.getState()
    const currentSnapshot = snapshots.get(service)
    if (currentSnapshot && isSameDataServiceState(currentSnapshot, nextSnapshot)) return currentSnapshot

    snapshots.set(service, nextSnapshot)

    return nextSnapshot
}

export function useProjectState(service: DataService = dataService): DataServiceState {
    return useSyncExternalStore(
        (onStoreChange) => {
            service.addEventListener('changed', onStoreChange)

            return () => service.removeEventListener('changed', onStoreChange)
        },
        () => getProjectStateSnapshot(service),
        () => getProjectStateSnapshot(service),
    )
}

