    registerUpdateDownload({ app, getWindow: getPrimaryWindow, https, ipcMain, shell });
    createWindow();
    void checkForUpdate({ app, getWindow: getPrimaryWindow, https });

    app.on('activate', () => {
        if (BrowserWindow.getAllWindows().length === 0) {
            createWindow();
